create or replace function public.accounting_asset_code(p_method text) returns text language sql immutable set search_path=public as $$ select case lower(coalesce(p_method,'')) when 'cash' then '1000' when 'bank' then '1010' when 'card' then '1010' when 'debit_card' then '1010' when 'upi' then '1020' when 'upi_qr' then '1020' when 'wallet' then '1030' when 'aeps' then '1040' when 'aeps_portal' then '1040' when 'dmt' then '1050' when 'dmt_portal' then '1050' when 'credit_card' then '1060' else '1400' end $$;
create sequence if not exists public.journal_entry_seq;
create or replace function public.post_journal_entry(p_entry_date date,p_source_type text,p_source_id uuid,p_description text,p_lines jsonb,p_posted_by uuid default auth.uid()) returns uuid language plpgsql security definer set search_path=public as $$ declare v_entry_id uuid;v_num text;v_d numeric:=0;v_c numeric:=0;v_line jsonb;v_code text;v_account uuid;v_no int:=0;begin if auth.uid() is null and auth.role()<>'service_role' and current_user<>'postgres' then raise exception 'Not authenticated';end if;if current_user<>'postgres' and auth.role()<>'service_role' and not public.is_back_office() then raise exception 'Forbidden';end if;if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Journal requires lines';end if;if p_source_id is not null then select id into v_entry_id from public.journal_entries where source_type=p_source_type and source_id=p_source_id;if v_entry_id is not null then return v_entry_id;end if;end if;for v_line in select * from jsonb_array_elements(p_lines) loop v_d:=v_d+round(coalesce((v_line->>'debit')::numeric,0),2);v_c:=v_c+round(coalesce((v_line->>'credit')::numeric,0),2);end loop;if abs(v_d-v_c)>0.005 then raise exception 'Unbalanced journal: debit %, credit %',v_d,v_c;end if;if v_d<=0 then raise exception 'Journal total must be positive';end if;v_num:='JE-'||lpad(nextval('public.journal_entry_seq')::text,8,'0');insert into public.journal_entries(entry_number,entry_date,source_type,source_id,description,posted_by) values(v_num,coalesce(p_entry_date,current_date),p_source_type,p_source_id,p_description,p_posted_by) returning id into v_entry_id;for v_line in select * from jsonb_array_elements(p_lines) loop v_no:=v_no+1;v_code:=v_line->>'account_code';select id into v_account from public.accounting_accounts where code=v_code and is_active;if v_account is null then raise exception 'Unknown accounting account %',v_code;end if;insert into public.journal_lines(journal_entry_id,account_id,line_no,debit,credit,description) values(v_entry_id,v_account,v_no,round(coalesce((v_line->>'debit')::numeric,0),2),round(coalesce((v_line->>'credit')::numeric,0),2),v_line->>'description');end loop;return v_entry_id;end $$;
create or replace function public.trg_journal_immutable() returns trigger language plpgsql set search_path=public as $$ begin if tg_op='DELETE' or (tg_op='UPDATE' and (old.debit,old.credit,old.account_id,old.journal_entry_id) is distinct from (new.debit,new.credit,new.account_id,new.journal_entry_id)) then raise exception 'Posted journal lines are immutable';end if;return coalesce(new,old);end $$;
create or replace function public.trg_journal_entry_immutable() returns trigger language plpgsql set search_path=public as $$ begin if tg_op='DELETE' then raise exception 'Posted journal entries are immutable';end if;if tg_op='UPDATE' and old.status='posted' and (new.entry_number,new.entry_date,new.source_type,new.source_id,new.description,new.posted_by) is distinct from (old.entry_number,old.entry_date,old.source_type,old.source_id,old.description,old.posted_by) then raise exception 'Posted journal entries are immutable';end if;return new;end $$;
create or replace function public.trg_journal_balance_check() returns trigger language plpgsql set search_path=public as $$ declare d numeric;c numeric;begin select coalesce(sum(debit),0),coalesce(sum(credit),0) into d,c from public.journal_lines where journal_entry_id=coalesce(new.journal_entry_id,old.journal_entry_id);if abs(d-c)>0.005 then raise exception 'Journal entry % is unbalanced: debit %, credit %',coalesce(new.journal_entry_id,old.journal_entry_id),d,c;end if;return null;end $$;
drop trigger if exists journal_lines_immutable on public.journal_lines;create trigger journal_lines_immutable before update or delete on public.journal_lines for each row execute function public.trg_journal_immutable();
drop trigger if exists journal_entries_immutable on public.journal_entries;create trigger journal_entries_immutable before update or delete on public.journal_entries for each row execute function public.trg_journal_entry_immutable();
drop trigger if exists journal_lines_balance_check on public.journal_lines;create constraint trigger journal_lines_balance_check after insert or update or delete on public.journal_lines deferrable initially deferred for each row execute function public.trg_journal_balance_check();
create or replace function public.trg_post_cash_entry_journal() returns trigger language plpgsql security definer set search_path=public as $$ declare a text;dr text;cr text;begin if new.amount<=0 then return new;end if;a:=public.accounting_asset_code(new.method);if new.direction='in' then dr:=a;cr:=case new.ref_type when 'return' then '5100' when 'transaction' then '4010' else '1400' end;else cr:=a;dr:=case new.ref_type when 'expense' then '6000' when 'invoice' then '1300' when 'quick_sale' then '1400' when 'purchase' then '2000' when 'return' then '5100' when 'transaction' then '1400' when 'day_close' then '3000' else '1400' end;end if;perform public.post_journal_entry(new.entry_date,'cash_entry',new.id,coalesce(new.description,'Cash movement'),jsonb_build_array(jsonb_build_object('account_code',dr,'debit',round(new.amount,2),'credit',0),jsonb_build_object('account_code',cr,'debit',0,'credit',round(new.amount,2))),null);return new;end $$;
drop trigger if exists cash_entry_journal on public.cash_entries;create trigger cash_entry_journal after insert on public.cash_entries for each row execute function public.trg_post_cash_entry_journal();
create or replace function public.trg_post_stock_journal() returns trigger language plpgsql security definer set search_path=public as $$ declare a numeric;begin a:=round(abs(new.qty_change)*coalesce(new.unit_cost,0),2);if a<=0 then return new;end if;if new.movement_type='PURCHASE' then perform public.post_journal_entry(new.movement_date,'stock_movement',new.id,'Purchase inventory',jsonb_build_array(jsonb_build_object('account_code','1200','debit',a,'credit',0),jsonb_build_object('account_code','2000','debit',0,'credit',a)));elsif new.movement_type='SALE' then perform public.post_journal_entry(new.movement_date,'stock_movement',new.id,'Cost of goods sold',jsonb_build_array(jsonb_build_object('account_code','5000','debit',a,'credit',0),jsonb_build_object('account_code','1200','debit',0,'credit',a)));elsif new.movement_type in ('SALES_RETURN','RETURN') then perform public.post_journal_entry(new.movement_date,'stock_movement',new.id,'Sales return inventory reversal',jsonb_build_array(jsonb_build_object('account_code','1200','debit',a,'credit',0),jsonb_build_object('account_code','5000','debit',0,'credit',a)));elsif new.movement_type='PURCHASE_RETURN' then perform public.post_journal_entry(new.movement_date,'stock_movement',new.id,'Purchase return inventory reversal',jsonb_build_array(jsonb_build_object('account_code','2000','debit',a,'credit',0),jsonb_build_object('account_code','1200','debit',0,'credit',a)));end if;return new;end $$;
drop trigger if exists stock_movement_journal on public.stock_movements;create trigger stock_movement_journal after insert on public.stock_movements for each row execute function public.trg_post_stock_journal();
create or replace function public.trg_post_settlement_journal() returns trigger language plpgsql security definer set search_path=public as $$ declare s text;d text;begin if new.status<>'success' then return new;end if;select public.accounting_asset_code(type) into s from public.payment_instruments where id=new.source_instrument_id;select public.accounting_asset_code(type) into d from public.payment_instruments where id=new.dest_instrument_id;if s is null then s:='1400';end if;if d is null then d:='1400';end if;if s<>d then perform public.post_journal_entry(new.settlement_date,'settlement',new.id,'Settlement '||new.settlement_number,jsonb_build_array(jsonb_build_object('account_code',d,'debit',new.amount,'credit',0),jsonb_build_object('account_code',s,'debit',0,'credit',new.amount)));end if;return new;end $$;
drop trigger if exists settlement_journal on public.settlements;create trigger settlement_journal after insert on public.settlements for each row execute function public.trg_post_settlement_journal();
create or replace view public.trial_balance with (security_invoker=true) as select a.code,a.name,a.account_type,coalesce(sum(l.debit),0)::numeric(18,2) total_debit,coalesce(sum(l.credit),0)::numeric(18,2) total_credit,case when a.account_type in ('asset','expense','contra_income') then coalesce(sum(l.debit-l.credit),0) else coalesce(sum(l.credit-l.debit),0) end::numeric(18,2) balance from public.accounting_accounts a left join public.journal_lines l on l.account_id=a.id left join public.journal_entries e on e.id=l.journal_entry_id and e.status='posted' group by a.id order by a.code;
revoke execute on function public.trg_post_cash_entry_journal() from public,anon,authenticated;
revoke execute on function public.trg_post_stock_journal() from public,anon,authenticated;
revoke execute on function public.trg_post_settlement_journal() from public,anon,authenticated;
